'use strict';
(()=>{
 const G=JustinGame,game=window.justinClicker,stage=document.getElementById('stage'),button=document.createElement('button');button.id='backdrops-open';button.type='button';button.textContent='backdrops';document.querySelector('.nonsense-lab').append(button);
 const dialog=document.createElement('dialog');dialog.className='online-dialog backdrop-dialog';dialog.setAttribute('aria-label','Backdrop shop');dialog.innerHTML='<div class="online-dialog-head"><div><h2>Backdrops</h2></div><button type="button" aria-label="Close backdrops">×</button></div><div class="backdrop-toolbar"><strong id="backdrop-wallet"></strong></div><p class="backdrop-help">Buy once. Equip anytime.</p><div id="backdrop-grid"></div>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();
 const groups=['Minecraft','Star Wars','NASA','Project Hail Mary','Odds & ends','Basics','Special'],sections=new Map();for(const group of groups){const section=document.createElement('section'),heading=document.createElement('h3'),grid=document.createElement('div');section.className='backdrop-category';heading.textContent=group.toUpperCase();grid.className='backdrop-category-grid';section.append(heading,grid);document.getElementById('backdrop-grid').append(section);sections.set(group,grid)}
 const site=document.createElement('div');site.id='site-backdrop';site.hidden=true;site.setAttribute('aria-hidden','true');const ambient=document.createElement('canvas');ambient.hidden=true;site.append(ambient);document.body.prepend(site);const ambientCtx=ambient.getContext('2d');let ambientAt=0;function resizeAmbient(){const scale=Math.min(1,1600/innerWidth,1200/innerHeight);ambient.width=Math.ceil(innerWidth*scale);ambient.height=Math.ceil(innerHeight*scale)}window.addEventListener('resize',resizeAmbient);resizeAmbient();const cards=new Map();let current='plain',generation=0,art=null,artW=0,artH=0;
 for(const b of G.backdrops){const card=document.createElement('article');card.className='backdrop-card';card.dataset.backdrop=b.id;const image=document.createElement('div');image.className='backdrop-preview';const index=G.backdrops.filter(x=>x.group===b.group).indexOf(b)+1,label=b.group+' background '+index;if(b.thumb){const img=document.createElement('img');img.src=b.thumb;img.loading='lazy';img.decoding='async';img.alt=label;image.append(img)}else image.classList.add(b.animated?'preview-justinverse':'preview-plain');const buy=document.createElement('button');buy.type='button';buy.onclick=()=>{game.backdropAction(b.id);render()};card.append(image,buy);sections.get(b.group).append(card);cards.set(b.id,{card,buy,label})}
 function render(){const s=game.snapshot();document.getElementById('backdrop-wallet').textContent=Math.floor(s.bank).toLocaleString()+' points';for(const b of G.backdrops){const {card,buy,label}=cards.get(b.id),owned=s.backdrops.includes(b.id),equipped=s.backdrop===b.id;card.classList.toggle('is-equipped',equipped);buy.disabled=equipped||!owned&&(b.adminOnly||s.bank<b.cost);buy.textContent=equipped?'equipped':owned?'equip':b.adminOnly?'admin gift':b.cost.toLocaleString()+' pts';buy.setAttribute('aria-label',equipped?'Equipped '+label:owned?'Equip '+label:b.adminOnly?label+' · admin gift only':'Buy '+label+' for '+b.cost+' points')}}
 button.onclick=()=>{render();dialog.showModal()};setInterval(()=>{if(dialog.open&&!document.hidden)render()},500);
 const paletteCache=new Map();
 function palette(rgb){document.body.style.setProperty('--scene-paper',rgb.map(v=>Math.round(255*.88+v*.12)).join(','));document.body.style.setProperty('--scene-shadow',rgb.map(v=>Math.round(v*.25)).join(','))}
 function tint(b){if(paletteCache.has(b.id)){palette(paletteCache.get(b.id));return}palette([90,115,145]);const image=new Image();image.onload=()=>{try{const c=document.createElement('canvas');c.width=c.height=16;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(image,0,0,16,16);const pixels=x.getImageData(0,0,16,16).data,rgb=[0,0,0];for(let i=0;i<pixels.length;i+=4)for(let k=0;k<3;k++)rgb[k]+=pixels[i+k]/256;paletteCache.set(b.id,rgb);if(current===b.id)palette(rgb)}catch{}image.onload=null;image.src=''};image.src=b.src}
 function sync(s){const next=s.backdrop||'plain';if(next===current)return;current=next;generation++;ambientAt=0;stage.classList.toggle('has-backdrop',next!=='plain');document.body.classList.toggle('has-site-backdrop',next!=='plain');site.hidden=next==='plain';ambient.hidden=next!=='justinverse';site.style.backgroundImage='none';if(next==='justinverse'){palette([92,68,145]);return}if(next==='plain')return;const b=G.backdrops.find(b=>b.id===next);if(b?.src){site.style.backgroundImage='url("'+b.src+'")';tint(b)}}

 const stars=Array.from({length:50},(_,i)=>({x:((i*157+31)%997)/997,y:((i*263+89)%991)/991,size:i%4===0?2:1}));
 function draw(ctx,w,h,t,impact,gentle){if(current==='plain')return;if(current!=='justinverse')return;
  const time=gentle?0:t;if(!art||artW!==w||artH!==h){artW=w;artH=h;art=document.createElement('canvas');art.width=Math.ceil(w);art.height=Math.ceil(h);const c=art.getContext('2d'),g=c.createRadialGradient(w*.3,h*.25,0,w*.45,h*.4,w*.8);g.addColorStop(0,'#643a92');g.addColorStop(.45,'#17204f');g.addColorStop(1,'#050711');c.fillStyle=g;c.fillRect(0,0,w,h)}ctx.drawImage(art,0,0,w,h);ctx.save();for(const s of stars){ctx.globalAlpha=.4+.4*Math.sin(time*.5+s.x*6)**2;ctx.fillStyle=s.size===2?'#b6faff':'#fff';ctx.fillRect((s.x*w+time*(s.size===2?5:2))%w,s.y*h,s.size,s.size)}ctx.globalAlpha=.3;ctx.strokeStyle='#85baff';ctx.lineWidth=1;for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(w*.5,h*.7,w*(.16+i*.075),h*(.06+i*.028),Math.sin(time*.15)*.1,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=.8;for(let i=0;i<3;i++){const a=time*.18+i*Math.PI*2/3,x=w*.5+Math.cos(a)*w*.34,y=h*.55+Math.sin(a)*h*.27;ctx.fillStyle=['#a7f4e8','#ffbbdc','#dfd27a'][i];ctx.beginPath();ctx.arc(x,y,7+i*3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffffff55';ctx.beginPath();ctx.ellipse(x,y,19+i*4,5+i, -.4,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=.7;ctx.fillStyle='#eee';ctx.font='10px monospace';ctx.fillText('THE JUSTIN DIMENSION / visitor parking only',14,h-22);ctx.restore();
 }
 function ambientFrame(ms){requestAnimationFrame(ambientFrame);if(current!=='justinverse'||document.hidden||document.querySelector('dialog[open]')||ms-ambientAt<32)return;const gentle=document.getElementById('gentle').checked;if(gentle&&ambientAt)return;ambientAt=ms;draw(ambientCtx,ambient.width,ambient.height,ms/1000,0,gentle)}window.JustinBackdrops={sync};sync(game.snapshot());requestAnimationFrame(ambientFrame);
})();
